/**
 * Founder-approved ordered rebuild of an episode row (design 4994db25,
 * approved at revision 1edd750c; build authorized 2026-11-01): inserts the
 * canonical turns listed in RECEIPT_PATH at their block boundaries, keeping
 * every existing byte, then makes the episode's embeddings current.
 *
 * Inert until a receipt generated by
 * server/scripts/generate-episode-rebuild-receipt.ts is committed and
 * approved.
 *
 * One transaction (server/services/episode-ordered-merge.ts decides it):
 *   - the episode row is locked FOR UPDATE, the same row lock the projection
 *     takes, so every other episode writer waits and lands after the rebuild;
 *   - every canonical per-turn row in the episode window is locked FOR SHARE,
 *     and each listed row must still match its entry;
 *   - the locked content must hash to the receipt's old content, and the
 *     merge must hash to the receipt's approved new content;
 *   - the previous text is written to episode_content_snapshots (insert only)
 *     in the same transaction as the UPDATE, so it can be put back exactly.
 * A re-run after success finds the approved content and writes nothing. A
 * refusal is reported, never forced, and does not fail the deploy.
 *
 * No database guard on episode content exists yet (no triggers on
 * conversation_memories). When the append-only guard of design fc90e95a
 * lands, this write must go through its audited repair route.
 */
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Pool } from '@neondatabase/serverless';
import type { DataOpResult } from '../run-data-ops';
import { CREATED_AT_SQL, PER_TURN_ARC, PER_TURN_TAG, sha256, type SourceRow } from '../../server/services/episode-backfill';
import {
  ORDERED_MERGE_SNAPSHOT_REASON, planOrderedMergeApply, type OrderedMergeReceipt,
} from '../../server/services/episode-ordered-merge';
import { ensureEmbeddings, productionDeps, type BackfillPool, type EmbeddingDeps } from './backfill-episode-turns';

export const RECEIPT_PATH = join(dirname(fileURLToPath(import.meta.url)), 'rebuild-episode-ordered.receipt.json');

export type RebuildOutcome =
  | { status: 'merged'; inserted: number; existing: number; snapshotId: string }
  | { status: 'complete' }
  | { status: 'refused'; reason: string; rowId?: string };

const toSource = (r: any): SourceRow => ({ id: r.id, content: r.content, createdAt: r.created_at, arcName: r.arc_name, tags: r.tags });

/** Apply one approved receipt in a single transaction. Exported so its rules are tested against real PostgreSQL. */
export async function applyRebuild(pool: BackfillPool, receipt: OrderedMergeReceipt): Promise<RebuildOutcome> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const episode = (await client.query(
      `SELECT title, content, ${CREATED_AT_SQL} AS created_at FROM conversation_memories WHERE id = $1 FOR UPDATE`, [receipt.episodeId],
    )).rows[0];
    let outcome: RebuildOutcome;
    if (!episode || typeof episode.content !== 'string') {
      outcome = { status: 'refused', reason: 'episode row missing' };
    } else if (episode.title !== receipt.episodeTitle) {
      outcome = { status: 'refused', reason: 'episode title differs from the receipt' };
    } else if (episode.created_at !== receipt.episodeCreatedAt) {
      outcome = { status: 'refused', reason: 'episode start differs from the receipt' };
    } else {
      const rows = (await client.query(
        `SELECT id, content, ${CREATED_AT_SQL} AS created_at, arc_name, tags FROM conversation_memories
          WHERE arc_name = $1 AND $2 = ANY(tags) AND ${CREATED_AT_SQL} >= $3
          FOR SHARE`,
        [PER_TURN_ARC, PER_TURN_TAG, receipt.episodeCreatedAt],
      )).rows.map(toSource);
      const plan = planOrderedMergeApply(receipt, episode.content, rows);
      if (plan.status === 'merge') {
        const snapshot = (await client.query(
          `INSERT INTO episode_content_snapshots (episode_id, reason, old_content, old_content_sha256, new_content_sha256, receipt_list_sha256)
           VALUES ($1, $2, $3, $4, $5, $6) RETURNING id`,
          [receipt.episodeId, ORDERED_MERGE_SNAPSHOT_REASON, episode.content, sha256(episode.content), receipt.newContentSha256, receipt.listSha256],
        )).rows[0];
        await client.query('UPDATE conversation_memories SET content = $2 WHERE id = $1', [receipt.episodeId, plan.newContent]);
        outcome = { status: 'merged', inserted: plan.entries.length, existing: plan.existing.length, snapshotId: snapshot.id };
      } else {
        outcome = plan.status === 'complete' ? { status: 'complete' } : { status: 'refused', reason: plan.reason, rowId: plan.rowId };
      }
    }
    await client.query(outcome.status === 'merged' ? 'COMMIT' : 'ROLLBACK');
    return outcome;
  } catch (e) {
    await client.query('ROLLBACK').catch(() => undefined);
    throw e;
  } finally {
    client.release();
  }
}

export function describe(outcome: RebuildOutcome, embeddings: string): string {
  const head = outcome.status === 'merged'
    ? `inserted ${outcome.inserted} turn(s) in order around ${outcome.existing} existing block(s); previous text in snapshot ${outcome.snapshotId}`
    : outcome.status === 'complete'
      ? 'already the approved content; nothing written'
      : `REFUSED, nothing written: ${outcome.reason}${outcome.rowId ? ` (${outcome.rowId})` : ''}`;
  return `episode ordered rebuild: ${head}; embeddings: ${embeddings}`;
}

/** The data-op body with its embedding dependencies injected. */
export async function runRebuild(pool: BackfillPool, receipt: OrderedMergeReceipt, deps: EmbeddingDeps): Promise<DataOpResult> {
  const outcome = await applyRebuild(pool, receipt);
  const embeddings = outcome.status === 'refused'
    ? 'not checked (rebuild refused)'
    : await ensureEmbeddings(pool, receipt.episodeId, deps);
  return { applied: outcome.status === 'merged', detail: describe(outcome, embeddings) };
}

export async function run(pool: Pool): Promise<DataOpResult> {
  if (!existsSync(RECEIPT_PATH)) return { applied: false, detail: 'no approved episode rebuild receipt; nothing to do' };
  const receipt = JSON.parse(readFileSync(RECEIPT_PATH, 'utf8')) as OrderedMergeReceipt;
  const p = pool as unknown as BackfillPool;
  try {
    return await runRebuild(p, receipt, await productionDeps(p));
  } finally {
    // server/db opened its own pool on import; close it so the pre-deploy
    // process exits promptly instead of waiting on idle connections.
    const { closeDbConnections } = await import('../../server/db');
    await closeDbConnections().catch(() => undefined);
  }
}
